<template>
  <section class="invitations-page" aria-labelledby="invitations-title">
    <header class="page-heading"><div><span class="eyebrow">ONBOARDING ACCESS</span><h2 id="invitations-title">邀请码管理</h2><p>创建一次性开户凭证。租户完成注册后，邀请码将永久失效。</p></div><el-button type="primary" @click="createDialogVisible = true">新增邀请码</el-button></header>
    <section class="lifecycle-strip" aria-label="邀请码生命周期统计"><div class="lifecycle-intro"><span>开户通道</span><small>INVITATION LIFECYCLE</small></div><div v-for="metric in metrics" :key="metric.key" class="lifecycle-metric"><span>{{ metric.label }}</span><strong>{{ metric.value }}</strong></div></section>
    <section class="invitation-panel" aria-label="邀请码列表">
      <form class="filters" @submit.prevent="applyFilters"><el-select v-model="filters.status" clearable placeholder="全部状态" aria-label="按邀请码状态筛选"><el-option label="可用" value="ACTIVE" /><el-option label="已使用" value="USED" /><el-option label="已禁用" value="DISABLED" /></el-select><el-select v-model="filters.expiry" clearable placeholder="全部有效期" aria-label="按邀请码有效期筛选"><el-option label="仍在有效期内" value="VALID" /><el-option label="24小时内到期" value="EXPIRING_SOON" /><el-option label="已经到期" value="EXPIRED" /></el-select><el-button native-type="submit">筛选</el-button><el-button text @click="resetFilters">重置</el-button></form>
      <p v-if="error" class="error-message" role="alert">{{ error }}</p>
      <div class="table-wrap" :aria-busy="loading"><table class="invitation-table"><thead><tr><th>邀请码</th><th>状态</th><th>可用时间</th><th>注册租户</th><th>创建时间</th><th class="actions-col">操作</th></tr></thead><tbody><tr v-for="invitation in invitations" :key="invitation.id"><td><code>{{ invitation.code }}</code></td><td><el-tag :type="statusType(invitation.status)" effect="plain">{{ statusLabel(invitation.status) }}</el-tag><el-tag v-if="isExpiringSoon(invitation)" class="expiry-tag" type="warning" effect="plain">24小时内到期</el-tag></td><td><span>{{ formatTime(invitation.validFrom) }}</span><span class="range-arrow">至</span><span>{{ formatTime(invitation.validUntil) }}</span></td><td>{{ usedTenantLabel(invitation.usedTenant) }}</td><td>{{ formatTime(invitation.createTime) }}</td><td class="actions-col"><el-button v-if="invitation.status === 'ACTIVE'" text type="danger" @click="disableInvitation(invitation)">立即禁用</el-button><span v-else class="muted">{{ invitation.status === 'USED' ? '已完成开户' : '已禁用' }}</span></td></tr><tr v-if="!loading && invitations.length === 0"><td colspan="6" class="empty-state">没有符合条件的邀请码</td></tr></tbody></table></div>
      <footer class="table-footer"><span>共 {{ total }} 条邀请码</span><el-pagination v-model:current-page="page" v-model:page-size="pageSize" layout="prev, pager, next" :total="total" :page-sizes="[10, 20, 50]" @current-change="loadInvitations" @size-change="changePageSize" /></footer>
    </section>
    <el-dialog v-model="createDialogVisible" title="新增邀请码" width="500px" :close-on-click-modal="false"><p class="dialog-context">邀请码在有效期内只能使用一次；注册完成后自动标记为已使用。</p><el-form label-position="top" @submit.prevent="createInvitation"><el-form-item label="可用时间范围"><el-date-picker v-model="createForm.validRange" type="datetimerange" range-separator="至" start-placeholder="开始时间" end-placeholder="结束时间" value-format="YYYY-MM-DDTHH:mm:ssZ" style="width: 100%" /></el-form-item></el-form><template #footer><el-button @click="createDialogVisible = false">取消</el-button><el-button type="primary" :loading="creating" @click="createInvitation">生成邀请码</el-button></template></el-dialog>
    <el-dialog v-model="codeDialogVisible" title="邀请码已生成" width="480px"><p class="dialog-context">请安全地发送给待开户的租户管理员。</p><div class="code-reveal"><code>{{ createdCode }}</code><el-button :disabled="!createdCode" @click="copyCode">复制</el-button></div><template #footer><el-button type="primary" @click="codeDialogVisible = false">完成</el-button></template></el-dialog>
  </section>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { http } from '../../api/http'
const invitations = ref([]), total = ref(0), page = ref(1), pageSize = ref(20), loading = ref(false), creating = ref(false), error = ref('')
const createDialogVisible = ref(false), codeDialogVisible = ref(false), createdCode = ref('')
const filters = reactive({ status: '', expiry: '' }), createForm = reactive({ validRange: defaultRange() })
const metrics = computed(() => [{ key: 'active', label: '当前页可用', value: invitations.value.filter(isAvailable).length }, { key: 'expiring', label: '24小时内到期', value: invitations.value.filter(isExpiringSoon).length }, { key: 'used', label: '当前页已使用', value: invitations.value.filter(item => item.status === 'USED').length }])
function defaultRange() { const from = new Date(); const until = new Date(from.getTime() + 7 * 24 * 60 * 60 * 1000); return [from.toISOString(), until.toISOString()] }
function requestParams() { return { page: page.value, pageSize: pageSize.value, status: filters.status || undefined, expiry: filters.expiry || undefined } }
async function loadInvitations() { loading.value = true; error.value = ''; try { const response = await http.get('/platform/invitations', { params: requestParams() }); const data = response.data?.data || {}; invitations.value = data.items || []; total.value = data.total || 0; page.value = data.page || page.value; pageSize.value = data.pageSize || pageSize.value } catch (cause) { error.value = cause.response?.data?.msg || '邀请码列表暂时无法加载' } finally { loading.value = false } }
async function applyFilters() { page.value = 1; await loadInvitations() }
async function resetFilters() { filters.status = ''; filters.expiry = ''; await applyFilters() }
async function changePageSize(size) { pageSize.value = size; page.value = 1; await loadInvitations() }
async function createInvitation() { const [validFrom, validUntil] = createForm.validRange || []; if (!validFrom || !validUntil || new Date(validUntil) <= new Date(validFrom)) { ElMessage.error('请选择有效的时间范围'); return } creating.value = true; try { const response = await http.post('/platform/invitations', { validFrom, validUntil }); createdCode.value = response.data?.data?.code || ''; createDialogVisible.value = false; codeDialogVisible.value = true; createForm.validRange = defaultRange(); ElMessage.success('邀请码已生成'); await loadInvitations() } catch (cause) { ElMessage.error(cause.response?.data?.msg || '生成邀请码失败') } finally { creating.value = false } }
async function disableInvitation(invitation) { try { await ElMessageBox.confirm(`邀请码“${invitation.code}”将立即失效，尚未注册的租户将无法使用它。`, '确认禁用邀请码', { confirmButtonText: '立即禁用', cancelButtonText: '取消', type: 'warning' }) } catch { return } try { await http.post(`/platform/invitations/${invitation.id}/disable`); ElMessage.success('邀请码已禁用'); await loadInvitations() } catch (cause) { ElMessage.error(cause.response?.data?.msg || '禁用邀请码失败') } }
async function copyCode() { try { await navigator.clipboard.writeText(createdCode.value); ElMessage.success('邀请码已复制') } catch { ElMessage.error('复制失败，请手动复制邀请码') } }
function statusLabel(status) { return ({ ACTIVE: '可用', USED: '已使用', DISABLED: '已禁用' })[status] || status }
function statusType(status) { return ({ ACTIVE: 'success', USED: 'info', DISABLED: 'danger' })[status] || 'info' }
function isAvailable(invitation) { if (invitation.status !== 'ACTIVE' || !invitation.validFrom || !invitation.validUntil) return false; const now = Date.now(); return new Date(invitation.validFrom).getTime() <= now && new Date(invitation.validUntil).getTime() >= now }
function isExpiringSoon(invitation) { if (!isAvailable(invitation)) return false; const millis = new Date(invitation.validUntil).getTime() - Date.now(); return millis > 0 && millis <= 24 * 60 * 60 * 1000 }
function usedTenantLabel(tenant) { return tenant ? `${tenant.name}（${tenant.code}）` : '—' }
function formatTime(value) { return value ? new Date(value).toLocaleString('zh-CN', { hour12: false }) : '—' }
onMounted(loadInvitations)
</script>

<style scoped>
.page-heading { display: flex; justify-content: space-between; align-items: flex-end; gap: 18px; margin-bottom: 25px; }.eyebrow { color: #526aaf; font-size: 11px; font-weight: 800; letter-spacing: .12em; }h2 { margin: 5px 0; color: #182541; font-size: 28px; letter-spacing: -.02em; }.page-heading p { margin: 0; color: #75819a; }.lifecycle-strip { display: grid; grid-template-columns: 1.4fr repeat(3, 1fr); overflow: hidden; margin-bottom: 18px; border: 1px solid #dfe5f1; border-radius: 12px; background: #fff; box-shadow: 0 8px 28px rgba(42, 58, 103, .06); }.lifecycle-intro, .lifecycle-metric { padding: 17px 20px; }.lifecycle-intro { display: flex; flex-direction: column; justify-content: center; background: #182b55; color: #fff; font-weight: 700; }.lifecycle-intro small { margin-top: 4px; color: #b8caed; font-size: 10px; letter-spacing: .12em; }.lifecycle-metric { border-left: 1px solid #e7eaf2; }.lifecycle-metric span { color: #75819a; font-size: 13px; }.lifecycle-metric strong { display: block; margin-top: 5px; color: #253b79; font-size: 25px; font-variant-numeric: tabular-nums; }.invitation-panel { overflow: hidden; border: 1px solid #e0e5f0; border-radius: 12px; background: #fff; box-shadow: 0 8px 28px rgba(42, 58, 103, .06); }.filters { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; padding: 18px 20px; border-bottom: 1px solid #e8ebf2; background: #fbfcff; }.filters :deep(.el-select) { width: 150px; }.table-wrap { overflow-x: auto; }.invitation-table { width: 100%; min-width: 860px; border-collapse: collapse; font-size: 14px; }.invitation-table th { padding: 12px 20px; background: #f6f8fc; color: #6e7991; font-size: 12px; font-weight: 700; letter-spacing: .04em; text-align: left; }.invitation-table td { padding: 15px 20px; border-top: 1px solid #edf0f5; color: #40506f; }.invitation-table tr:hover td { background: #fafbff; }.invitation-table code, .code-reveal code { color: #3f5fa5; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-weight: 700; }.expiry-tag { margin-left: 6px; }.range-arrow { margin: 0 6px; color: #9aa4b7; }.actions-col { text-align: right !important; white-space: nowrap; }.muted { color: #98a1b2; }.empty-state { padding: 38px !important; color: #8791a6 !important; text-align: center; }.table-footer { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 14px 20px; color: #778298; font-size: 13px; }.error-message { margin: 12px 20px; color: #ba3434; }.dialog-context { margin: 0 0 14px; color: #71809a; font-size: 13px; }.code-reveal { display: flex; align-items: center; gap: 12px; padding: 14px; border: 1px dashed #b9c8e8; border-radius: 9px; background: #f4f7ff; }.code-reveal code { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }@media (max-width: 720px) { .page-heading { align-items: flex-start; flex-direction: column; }.lifecycle-strip { grid-template-columns: repeat(3, 1fr); }.lifecycle-intro { display: none; }.lifecycle-metric:first-of-type { border-left: 0; } }@media (max-width: 520px) { .lifecycle-strip { grid-template-columns: 1fr; }.lifecycle-metric { border-left: 0; border-top: 1px solid #e7eaf2; }.table-footer { align-items: flex-start; flex-direction: column; } }@media (prefers-reduced-motion: reduce) { * { transition: none !important; } }
</style>
